css:
/* Layout: тёмный верстак с перфопанелью на фоне; шапка с выбором машины, сетка карточек-работ с иконками,
   в работе — «приборная панель» с цифрами для выбранной машины; на телефоне нижнее меню разделов.
   Гаражный стиль задуман тёмным в любой теме устройства. */
:root{
  color-scheme:dark;
  --bg:#0E1317; --peg:#1A222A; --surface:#161D24; --raised:#1D2630; --line:#29343F; --line-2:#36434F;
  --ink:#E7EDF2; --muted:#8C99A5; --dim:#5F6C78;
  --blue:#4F8FEA; --blue-ink:#9CC2F7; --blue-soft:#17263A;
  --amber:#F2B13A; --amber-ink:#0E1317; --amber-soft:#2E2412;
  --warn:#F07B63; --warn-soft:#33191440; --ok:#6CC48C;
  --f-display:"Russo One","Arial Black",system-ui,sans-serif;
  --f-body:"IBM Plex Sans",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  --f-mono:"IBM Plex Mono",ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  --r:14px;
}
*{box-sizing:border-box}
[hidden]{display:none!important}
html{background:var(--bg)}
body{background-color:var(--bg);background-image:radial-gradient(var(--peg) 1.6px,transparent 1.8px);background-size:22px 22px;color:var(--ink);font:15px/1.55 var(--f-body)}
body::before{content:"";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:10;background:var(--surface)}
.wrap{max-width:900px;margin:0 auto;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}
a{color:var(--blue-ink)}
button,input,select{font:inherit;color:inherit}
:focus-visible{outline:2px solid var(--amber);outline-offset:2px}

/* шапка */
header{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:color-mix(in srgb,var(--surface) 92%,transparent);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.head{display:flex;flex-direction:column;gap:12px;padding-block:14px 10px}
.brand{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.logo{width:38px;height:38px;border-radius:11px;background:var(--amber);display:grid;place-items:center;flex:none}
.logo svg{width:22px;height:22px;stroke:var(--amber-ink)}
.brand h1{font:24px/1 var(--f-display);margin:0;letter-spacing:.02em}
.brand .sub{color:var(--muted);font-size:13px;line-height:1.2}
.brand .t{display:flex;flex-direction:column;gap:3px;margin-right:auto}
.fam{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;margin-inline:-4px;padding:2px 4px}
.fam::-webkit-scrollbar{display:none}
.fam button{flex:none;border:1px solid var(--line-2);background:var(--raised);border-radius:999px;padding:7px 14px;cursor:pointer;font-size:13.5px;white-space:nowrap;color:var(--muted);font-weight:500}
.fam button:hover{color:var(--ink)}
.fam button[aria-pressed="true"]{background:var(--blue);border-color:var(--blue);color:#fff;font-weight:600}
.tabs{display:flex;gap:4px}
.tabs button{border:0;background:none;padding:6px 12px 9px;cursor:pointer;color:var(--muted);font-weight:500;border-bottom:2px solid transparent}
.tabs button[aria-selected="true"]{color:var(--ink);border-bottom-color:var(--amber)}
nav.bottom{display:none}

main{padding-block:20px 56px}
.search{position:relative;margin-bottom:14px}
.search input{width:100%;padding:12px 14px 12px 42px;border:1px solid var(--line-2);border-radius:var(--r);background:var(--surface);color:var(--ink)}
.search input::placeholder{color:var(--dim)}
.search svg{position:absolute;left:14px;top:50%;width:18px;height:18px;transform:translateY(-50%);stroke:var(--muted)}
.famnote{font-size:13px;color:var(--muted);margin:0 0 16px}
.famnote b{color:var(--amber);font-weight:600}

/* список работ */
.list{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px}
.card{display:flex;flex-direction:column;gap:8px;text-align:left;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:16px;cursor:pointer;min-width:0;color:var(--ink)}
.card:hover{border-color:var(--line-2);background:var(--raised)}
.ico{width:44px;height:44px;border-radius:12px;background:var(--blue-soft);display:grid;place-items:center;flex:none}
.ico svg{width:24px;height:24px;stroke:var(--blue-ink)}
.card h3{margin:2px 0 0;font-size:16.5px;font-weight:600;line-height:1.3;text-wrap:balance}
.card p{margin:0;color:var(--muted);font-size:13.5px}
.meta{display:flex;flex-wrap:wrap;gap:6px;margin-top:auto;padding-top:6px}
.pill{font-size:12px;padding:3px 9px;border-radius:999px;background:var(--raised);color:var(--muted);white-space:nowrap;border:1px solid var(--line)}
.pill.vid{background:var(--blue-soft);color:var(--blue-ink);border-color:transparent}
.lvl1{color:var(--ok)} .lvl2{color:var(--amber)}
.empty{color:var(--muted);padding:24px 0}

/* работа */
.back{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line-2);background:var(--raised);color:var(--ink);border-radius:999px;cursor:pointer;padding:6px 14px 6px 10px;margin-bottom:16px;font-weight:500;font-size:14px}
.dhead{display:flex;gap:14px;align-items:flex-start;margin-bottom:18px}
.dhead .ico{width:54px;height:54px;border-radius:14px}
.dhead .ico svg{width:28px;height:28px}
.dhead > div{min-width:0}
.detail h2{font:26px/1.15 var(--f-display);margin:2px 0 6px;text-wrap:balance}
.lead{color:var(--muted);margin:0;max-width:65ch}
.plate{background:linear-gradient(180deg,var(--raised),var(--surface));border:1px solid var(--line-2);border-radius:var(--r);padding:14px 16px;margin-bottom:24px}
.plate .cap{display:flex;align-items:center;gap:8px;font-size:11.5px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);margin-bottom:12px}
.plate .cap::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--amber);box-shadow:0 0 8px var(--amber)}
.plate dl{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px 20px;margin:0}
.plate dt{font-size:12.5px;color:var(--muted);margin-bottom:2px}
.plate dd{margin:0;font:500 17px/1.3 var(--f-mono);color:var(--amber);font-variant-numeric:tabular-nums}
.plate dd.txt{font:500 14px/1.45 var(--f-body);color:var(--ink)}
.plate .approx{font-size:12px;color:var(--dim);margin:14px 0 0;padding-top:10px;border-top:1px solid var(--line)}
section.blk{margin-bottom:26px}
section.blk h4{font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);margin:0 0 10px}
.tools{display:flex;flex-wrap:wrap;gap:8px}
.tools button,.tools span{border:1px solid var(--line-2);background:var(--surface);border-radius:999px;padding:5px 12px;font-size:13.5px;color:var(--muted)}
.tools button{cursor:pointer;color:var(--blue-ink);border-color:color-mix(in srgb,var(--blue) 45%,transparent)}
.tools button:hover{background:var(--blue-soft)}
ol.steps{list-style:none;counter-reset:s;margin:0;padding:0;display:flex;flex-direction:column;gap:0;max-width:70ch}
ol.steps li{counter-increment:s;display:grid;grid-template-columns:32px 1fr;gap:12px;position:relative;padding-bottom:14px}
ol.steps li:not(:last-child)::after{content:"";position:absolute;left:15px;top:32px;bottom:0;width:2px;background:var(--line)}
ol.steps li::before{content:counter(s);font:14px/30px var(--f-display);text-align:center;width:32px;height:32px;border-radius:50%;border:2px solid var(--amber);color:var(--amber);background:var(--bg);box-sizing:border-box;line-height:28px}
ol.steps li div{min-width:0;padding-top:4px}
.n{font:500 14px var(--f-mono);background:var(--amber-soft);color:var(--amber);padding:1px 6px;border-radius:5px;white-space:nowrap}
.warn{display:flex;gap:12px;background:color-mix(in srgb,var(--warn) 12%,var(--surface));border:1px solid color-mix(in srgb,var(--warn) 35%,transparent);color:var(--ink);border-radius:var(--r);padding:12px 16px;max-width:70ch}
.warn::before{content:"!";flex:none;width:22px;height:22px;border-radius:50%;background:var(--warn);color:var(--bg);font:14px/22px var(--f-display);text-align:center}
.warn p{margin:0}
.table{overflow-x:auto;background:var(--surface);border:1px solid var(--line);border-radius:var(--r)}
table{border-collapse:collapse;width:100%;font-size:14px}
th,td{text-align:left;padding:10px 14px;border-bottom:1px solid var(--line);vertical-align:top}
tr:last-child td{border-bottom:0}
th{font-size:12px;color:var(--muted);font-weight:500;text-transform:uppercase;letter-spacing:.06em}
td:first-child{font-weight:600;min-width:180px}

/* видео */
.vids{display:flex;flex-direction:column;gap:8px}
.vid-card{display:flex;align-items:center;gap:14px;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:12px 14px;min-width:0}
.vid-card:hover{border-color:var(--line-2)}
.vid-card a{flex:1;min-width:0;text-decoration:none;color:var(--ink);display:flex;flex-direction:column}
.vid-card a b{font-weight:600;overflow-wrap:anywhere}
.vid-card a small{color:var(--muted)}
.play{flex:none;width:40px;height:40px;border-radius:50%;background:var(--amber);display:grid;place-items:center}
.play::after{content:"";border-left:12px solid var(--amber-ink);border-top:8px solid transparent;border-bottom:8px solid transparent;margin-left:4px}
.del{border:0;background:none;color:var(--warn);cursor:pointer;font-size:13px;padding:4px}
.nov{color:var(--muted);font-size:14px;margin:0}
form.add{display:grid;gap:10px;background:var(--surface);border:1px dashed var(--blue);border-radius:var(--r);padding:14px;margin-top:12px}
form.add .row{display:flex;gap:8px;flex-wrap:wrap}
form.add input,form.add select{padding:10px 12px;border:1px solid var(--line-2);border-radius:10px;background:var(--bg);color:var(--ink);min-width:0;flex:1 1 200px}
.btn{border:0;border-radius:10px;background:var(--blue);color:#fff;padding:10px 16px;cursor:pointer;font-weight:600}
.btn:hover{filter:brightness(1.1)}
.msg{font-size:13px;margin:0;color:var(--muted)}
.msg.err{color:var(--warn)}
.owner-badge{font-size:12px;color:var(--amber);background:var(--amber-soft);padding:3px 10px;border-radius:999px}

/* инструмент и жидкости */
.entry{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:16px 18px;scroll-margin-top:190px}
.entry h3{margin:0 0 4px;font-size:18px;font-family:var(--f-display);font-weight:400;letter-spacing:.01em}
.entry > p{margin:0 0 12px;color:var(--muted);max-width:68ch}
.types{display:grid;gap:0;margin:0;padding:0;list-style:none}
.types li{display:grid;grid-template-columns:minmax(130px,200px) 1fr;gap:14px;padding:9px 0;border-top:1px solid var(--line)}
.types li b{font-weight:600}
.types li span{min-width:0;color:var(--ink)}
.tip{display:flex;gap:10px;margin:12px 0 0;font-size:13.5px;color:var(--ink);background:var(--amber-soft);border-radius:10px;padding:10px 12px}
.tip::before{content:"Совет";flex:none;font:600 11px/1.9 var(--f-body);text-transform:uppercase;letter-spacing:.08em;color:var(--amber)}
.stack{display:flex;flex-direction:column;gap:12px}
.tools button.part{color:var(--amber);border-color:color-mix(in srgb,var(--amber) 45%,transparent)}
.tools button.part:hover{background:var(--amber-soft)}
.brands-cap{font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);margin:14px 0 8px}
.brands{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:8px}
.brands li{display:flex;flex-direction:column;gap:2px;background:var(--raised);border:1px solid var(--line);border-radius:10px;padding:9px 12px;min-width:0}
.brands li b{font-weight:600}
.brands li span{font-size:12.5px;color:var(--muted)}
.bad{margin-top:12px;font-size:13.5px;background:color-mix(in srgb,var(--warn) 12%,var(--surface));border:1px solid color-mix(in srgb,var(--warn) 35%,transparent);border-radius:10px;padding:10px 12px}
.bad b{color:var(--warn)}
.bad span{color:var(--muted)}

/* регламент, симптомы, гараж */
.features{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;margin-bottom:16px}
.feature,.logbtn{display:flex;align-items:center;gap:12px;text-align:left;background:linear-gradient(135deg,var(--amber-soft),var(--surface) 70%);border:1px solid color-mix(in srgb,var(--amber) 35%,transparent);border-radius:var(--r);padding:14px;cursor:pointer;color:var(--ink);min-width:0;width:100%}
.feature .ico,.logbtn .ico{background:var(--amber);}
.feature .ico svg,.logbtn .ico svg{stroke:var(--amber-ink)}
.feature span:last-child,.logbtn span:last-child{display:flex;flex-direction:column;min-width:0}
.feature b,.logbtn b{font-size:16px}
.feature small,.logbtn small{color:var(--muted);font-size:13px}
.feature:hover,.logbtn:hover{border-color:var(--amber)}
.logbtn{margin-top:16px}
.approx-note{font-size:12.5px;color:var(--dim);margin:12px 0 0;max-width:70ch}
.linkbtn{border:0;background:none;color:var(--blue-ink);cursor:pointer;padding:2px 0;font-size:13.5px;font-weight:500;white-space:nowrap}
.linkbtn:hover{text-decoration:underline}
td:last-child{text-align:right}
.entry.starter{border-color:color-mix(in srgb,var(--amber) 45%,transparent)}
.sym h3{font-family:var(--f-body);font-weight:600;font-size:16.5px}
.sym.danger{border-color:color-mix(in srgb,var(--warn) 45%,transparent)}
.dangerpill{display:inline-block;margin:2px 0 6px;background:color-mix(in srgb,var(--warn) 18%,transparent);color:var(--warn);border-color:transparent}
.causes{margin:6px 0 12px;padding-left:20px;color:var(--ink);display:flex;flex-direction:column;gap:4px;max-width:68ch}
.chips{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px}
.chips button{border:1px solid var(--line-2);background:var(--raised);border-radius:999px;padding:7px 14px;cursor:pointer;color:var(--muted);font-weight:500}
.chips button[aria-pressed="true"]{background:var(--amber);border-color:var(--amber);color:var(--amber-ink);font-weight:600}
.carcard{background:linear-gradient(180deg,var(--raised),var(--surface));border:1px solid var(--line-2);border-radius:var(--r);padding:16px;margin-bottom:24px;display:flex;flex-direction:column;gap:14px}
.carhead{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
.carhead h3{margin:0;font:22px/1.15 var(--f-display);font-weight:400}
.carhead p{margin:4px 0 0;color:var(--muted);font-size:13.5px}
.carbtns{display:flex;gap:6px;align-items:flex-start}
.kmrow{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap;padding-top:12px;border-top:1px solid var(--line)}
.kmrow .cap{display:block;font-size:11.5px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}
.bigkm{font:500 28px/1.2 var(--f-mono);color:var(--amber);font-variant-numeric:tabular-nums}
.kmset{display:flex;gap:8px;min-width:0;flex:0 1 300px}
.kmset input{flex:1;min-width:0;padding:10px 12px;border:1px solid var(--line-2);border-radius:10px;background:var(--bg);color:var(--ink)}
.ghost{border:1px solid var(--line-2);background:transparent;color:var(--ink);border-radius:10px;padding:10px 14px;cursor:pointer;font-weight:500}
.ghost.sm{padding:5px 10px;font-size:13px}
.ghost.danger{color:var(--warn)}
.duelist,.loglist{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
.due{display:flex;justify-content:space-between;gap:12px;background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--line-2);border-radius:10px;padding:10px 14px}
.due-main{display:flex;flex-direction:column;min-width:0}
.due-main small{color:var(--muted);font-size:12.5px}
.due-side{display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex:none}
.stpill{font-size:12px;padding:2px 9px;border-radius:999px;white-space:nowrap}
.st-over{border-left-color:var(--warn)} .st-over .stpill{background:color-mix(in srgb,var(--warn) 18%,transparent);color:var(--warn)}
.st-soon{border-left-color:var(--amber)} .st-soon .stpill{background:var(--amber-soft);color:var(--amber)}
.st-ok{border-left-color:var(--ok)} .st-ok .stpill{background:color-mix(in srgb,var(--ok) 15%,transparent);color:var(--ok)}
.st-none .stpill{background:var(--raised);color:var(--muted)}
.gform{display:flex;flex-direction:column;gap:12px;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:16px}
.gform h3{margin:0;font-size:17px}
.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px 12px}
.gform label{display:flex;flex-direction:column;gap:4px;font-size:12.5px;color:var(--muted);min-width:0}
.gform label.wide{grid-column:1/-1}
.gform input,.gform select{padding:10px 12px;border:1px solid var(--line-2);border-radius:10px;background:var(--bg);color:var(--ink);font-size:15px;min-width:0;width:100%}
.gform .row{display:flex;gap:8px;flex-wrap:wrap}
.due-empty{list-style:none;color:var(--muted);font-size:14px;background:var(--surface);border:1px dashed var(--line-2);border-radius:10px;padding:12px 14px}
.duemore{list-style:none}
.duemore summary{cursor:pointer;color:var(--muted);font-size:13.5px;padding:6px 2px}
.duemore .duelist{margin-top:6px}
.duelist > li:has(> .duemore){list-style:none}
.loglist li{display:grid;grid-template-columns:110px 1fr auto;gap:12px;background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:10px 14px;align-items:start}
.logdate{display:flex;flex-direction:column;font-variant-numeric:tabular-nums}
.logdate span{font:500 13px var(--f-mono);color:var(--amber)}
.logbody{display:flex;flex-direction:column;min-width:0}
.logbody span{font-size:13.5px;overflow-wrap:anywhere}
.logbody small{color:var(--muted);font-size:12.5px;overflow-wrap:anywhere}
.logside{display:flex;flex-direction:column;align-items:flex-end;gap:2px}
.cost{font:500 13.5px var(--f-mono);white-space:nowrap}
.total{margin:12px 0 0;color:var(--muted)}
.total b{color:var(--ink);font-family:var(--f-mono);font-weight:500}
@media (max-width:640px){
  .loglist li{grid-template-columns:1fr auto}
  .logdate{grid-column:1/-1;flex-direction:row;gap:10px}
  .due{flex-direction:column}
  .due-side{flex-direction:row;align-items:center;justify-content:space-between}
  .kmset{flex-basis:100%}
  nav.bottom button{font-size:10.5px}
}

.tg{display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;border:1px solid var(--line-2);color:var(--muted);text-decoration:none;font-size:13.5px;font-weight:500}
.tg svg{width:18px;height:18px;stroke:currentColor}
.tg:hover{color:var(--blue-ink);border-color:color-mix(in srgb,var(--blue) 50%,transparent)}
.tgcard{display:flex;align-items:center;gap:14px;margin-top:28px;padding:14px 16px;border-radius:var(--r);border:1px solid var(--line);background:var(--surface);color:var(--ink);text-decoration:none}
.tgcard:hover{border-color:color-mix(in srgb,var(--blue) 50%,transparent)}
.tgico{flex:none;width:44px;height:44px;border-radius:50%;background:var(--blue-soft);display:grid;place-items:center}
.tgico svg{width:22px;height:22px;stroke:var(--blue-ink)}
.tgtext{display:flex;flex-direction:column;min-width:0;flex:1}
.tgtext small{color:var(--muted);font-size:13px}
.tgqr{flex:none;width:84px;height:84px;background:#fff;border-radius:8px;padding:3px;display:none}
.tgqr svg{width:100%;height:100%;display:block}
@media (min-width:760px){.tgqr:not(:empty){display:block}}

/* схемы */
.fig{margin:0;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:14px 14px 12px;overflow-x:auto}
.fig svg{display:block;width:100%;height:auto;min-width:420px;max-width:640px;margin:0 auto}
.fig.fig-sm svg{min-width:0;max-width:300px}
.fig figcaption{font-size:13px;color:var(--muted);margin-top:8px;text-align:center}
.fx-h{fill:var(--ink);font:600 15px var(--f-body)}
.fx-s{fill:var(--muted);font:500 12.5px var(--f-body)}
.fx-v{fill:var(--amber);font:500 14px var(--f-mono)}
.fx-w{fill:var(--warn)} .fx-a{fill:var(--amber)} .fx-on{fill:#2a1d0a}
.fx-b{fill:var(--blue-ink)} .fx-term{fill:#fff;font:700 12px var(--f-body)}
.fx-num{fill:#fff;font:700 13px var(--f-body)} .fx-numd{fill:var(--amber-ink);font:700 15px var(--f-body)}
.fx-shell{fill:#7d8790} .fx-thread{stroke:#5b646c;stroke-width:1.5}
.fx-metal{stroke:#9aa3ab} .fx-metalf{fill:#9aa3ab}
